using Erp.Abstractions.Modules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
namespace Erp.Modules.Purchasing; internal static class PurchasingEndpoints { public static void MapPurchasingEndpoints(this IEndpointRouteBuilder e) { var g = e.MapGroup("/api/v1/purchasing/orders").WithTags("Purchase Orders"); g.MapGet("/", (string? search, PurchaseOrderState? state, bool includeArchived, string? sort, bool descending, int page, int pageSize, IPurchaseOrderService s, CancellationToken t) => Run(() => s.SearchAsync(new(search, state, includeArchived, sort ?? "updated", descending, page < 1 ? 1 : page, pageSize < 1 ? 25 : pageSize), t))).RequirePermission(PurchasingPermissions.Read); g.MapGet("/{id:guid}", async (Guid id, IPurchaseOrderService s, CancellationToken t) => await s.GetAsync(id, t) is { } x ? Results.Ok(x) : Results.NotFound()).RequirePermission(PurchasingPermissions.Read); g.MapPost("/", (PurchaseOrderRequest r, IPurchaseOrderService s, CancellationToken t) => Run(() => s.CreateAsync(r, t), true)).RequirePermission(PurchasingPermissions.Manage); g.MapPut("/{id:guid}", (Guid id, PurchaseOrderRequest r, IPurchaseOrderService s, CancellationToken t) => Run(() => s.UpdateAsync(id, r, t))).RequirePermission(PurchasingPermissions.Manage); g.MapPost("/{id:guid}/send", (Guid id, PurchaseOrderTransitionRequest r, IPurchaseOrderService s, CancellationToken t) => Run(() => s.TransitionAsync(id, PurchaseOrderState.Sent, r.ConcurrencyStamp, t))).RequirePermission(PurchasingPermissions.Approve); g.MapPost("/{id:guid}/confirm", (Guid id, PurchaseOrderTransitionRequest r, IPurchaseOrderService s, CancellationToken t) => Run(() => s.TransitionAsync(id, PurchaseOrderState.Confirmed, r.ConcurrencyStamp, t))).RequirePermission(PurchasingPermissions.Approve); g.MapPost("/{id:guid}/cancel", (Guid id, PurchaseOrderTransitionRequest r, IPurchaseOrderService s, CancellationToken t) => Run(() => s.TransitionAsync(id, PurchaseOrderState.Cancelled, r.ConcurrencyStamp, t))).RequirePermission(PurchasingPermissions.Cancel); g.MapPost("/{id:guid}/archive", (Guid id, PurchaseOrderTransitionRequest r, IPurchaseOrderService s, CancellationToken t) => Run(() => s.SetArchivedAsync(id, r.ConcurrencyStamp, true, t))).RequirePermission(PurchasingPermissions.Archive); g.MapPost("/{id:guid}/reactivate", (Guid id, PurchaseOrderTransitionRequest r, IPurchaseOrderService s, CancellationToken t) => Run(() => s.SetArchivedAsync(id, r.ConcurrencyStamp, false, t))).RequirePermission(PurchasingPermissions.Archive); } private static async Task<IResult> Run<T>(Func<Task<T>> action, bool created = false) { try { var x = await action(); return created && x is PurchaseOrderDto o ? Results.Created($"/api/v1/purchasing/orders/{o.Id}", x) : Results.Ok(x); } catch (PurchasingValidationException ex) { return Results.ValidationProblem(ex.Errors); } catch (PurchasingConcurrencyException ex) { return Results.Conflict(new { error = ex.Message }); } catch (KeyNotFoundException) { return Results.NotFound(); } } }
